static acpi_status acpi_ds_result_stack_pop ( struct acpi_walk_state * walk_state ) { union acpi_generic_state * state ; ACPI_FUNCTION_NAME ( ds_result_stack_pop ) ; if ( walk_state -> results == NULL ) { ACPI_DEBUG_PRINT ( ( ACPI_DB_EXEC , "Result stack underflow - State=%p\n" , walk_state ) ) ; return ( AE_AML_NO_OPERAND ) ; } if ( walk_state -> result_size < ACPI_RESULTS_FRAME_OBJ_NUM ) { ACPI_ERROR ( ( AE_INFO , "Insufficient result stack size" ) ) ; return ( AE_AML_INTERNAL ) ; } state = acpi_ut_pop_generic_state ( & walk_state -> results ) ; acpi_ut_delete_generic_state ( state ) ; ACPI_DEBUG_PRINT ( ( ACPI_DB_EXEC , "Result=%p RemainingResults=%X State=%p\n" , state , walk_state -> result_count , walk_state ) ) ; return ( AE_OK ) ; } 